// Extract incoming attack telemetry from Suraksha-AI
const body = $input.item.json.body || $input.item.json;

const attackType = body.attack_type || 'SQL Injection';
const confidence = body.confidence || 0;
const severity = body.severity || 'High';
const url = body.url || '/api/login';
const method = body.method || 'POST';
const clientIp = body.client_ip || '127.0.0.1';
const payloadStr = body.payload || body.explanation || 'Malicious SQL pattern';
const blocked = body.blocked ? 'BLOCKED' : 'FLAGGED';

const incidentContext = `🚨 [SURAKSHA-AI ATTACK TELEMETRY EVENT]

• Attack Status: ${blocked}
• Attack Signature: ${attackType}
• Threat Severity: ${severity}
• AI Risk Score / Confidence: ${confidence}%
• Target Endpoint: ${method} ${url}
• Attacker IP Address: ${clientIp}
• Intercepted Payload: ${payloadStr}
• Event Timestamp: ${new Date().toISOString()}`;

return [{
  json: {
    incident_context: incidentContext,
    attack_type: attackType,
    severity: severity,
    confidence: confidence,
    url: url,
    client_ip: clientIp,
    payload: payloadStr,
    raw_event: body
  }
}];

// Task Router & Sub-Agent Dispatcher Node
const orchestratorOutput = $input.item.json.output || $input.item.json.text || 'Triage complete.';
const prevData = $node['Format Incident Telemetry'].json;

// Generate sub-agent task assignments based on attack severity & signature
const tasks = [];

// Sub-Agent 1: Threat Classification & Deep Analysis Agent
tasks.push({
  agent: 'Threat Classification Agent',
  status: 'COMPLETED',
  action: `Analyzed ${prevData.attack_type} payload with ${prevData.confidence}% confidence score.`
});

// Sub-Agent 2: Database & IP Security Agent
tasks.push({
  agent: 'IP Security & History Agent',
  status: prevData.severity === 'High' || prevData.severity === 'Critical' ? 'IP_TEMPORARY_BLOCK' : 'MONITORING',
  action: `Evaluated ${prevData.client_ip}. Assigned status ${prevData.severity === 'High' || prevData.severity === 'Critical' ? 'IP_TEMPORARY_BLOCK' : 'MONITORING'}.`
});

// Sub-Agent 3: Automated Remediation & Firewall Agent
tasks.push({
  agent: 'Firewall & Remediation Agent',
  status: 'ACTIVE',
  action: `Formulated defensive rule for ${prevData.url}. Payload pattern blocked at proxy level.`
});

// Sub-Agent 4: Incident Notification Agent
tasks.push({
  agent: 'Notification & Reporting Agent',
  status: 'QUEUED',
  action: 'Dispatching security alert payload to backend audit log & admin notification feed.'
});

return [{
  json: {
    orchestrator_summary: orchestratorOutput,
    assigned_sub_agent_tasks: tasks,
    incident_metadata: prevData
  }
}];
